export interface FloatingBadge {
  id: string;
  label: string;
  cost: number;
  type: 'itinerary' | 'activity';
  top: string;
  left: string;
}

export interface Spot {
  id: string;
  name: string;
  subtitle: string;
  cost: number;
  category: 'Heritage' | 'Fort' | 'Scenic' | 'Culture' | 'Beach' | 'Adventure' | 'Temple' | 'Nature';
  rating: number;
  reviewsCount: number;
  duration: string;
  bestTime: string;
  description: string;
  highlights: string[];
  wikiTitle: string;
  realPhotoUrl: string;
  lat: number;
  lng: number;
  speechQuote: string;
  guideMessage?: string;
  nextSpotName: string;
  floatingBadges: FloatingBadge[];
  panorama: {
    ambientColor: string;
    skyTop: string;
    skyHorizon: string;
    groundColor: string;
    accentGlow: string;
    monumentName: string;
    atmosphere: string;
  };
}

export interface Destination {
  id: string;
  name: string;
  state: string;
  region: 'North' | 'South' | 'West' | 'East' | 'Northeast' | 'Central';
  tagline: string;
  description: string;
  heroImage: string;
  startingPrice: number;
  lat: number;
  lng: number;
  spots: Spot[];
}

